glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec2 uv0;
out vec4 color;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return cc_matViewProj * pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 uv0;
in vec4 color;
layout(std140) uniform JiudingParams { vec4 params; };
uniform sampler2D maskTex;
uniform sampler2D flowTex;
vec4 frag () {
  float a = texture(maskTex, uv0).a;
  if (a < 0.002 || params.y <= 0.0) return vec4(0.0);
  vec2 q = vec2(uv0.x, 1.0 - uv0.y);
  float time = params.x;
  float curl = sin(q.y*18.0+time*1.8)*0.045 + sin(q.x*21.0-q.y*9.0+time*1.1)*0.025;
  vec2 advected = vec2(q.x*3.1+time*0.34+curl, q.y*2.2+sin(q.x*12.0+time*1.2)*0.11-time*0.065);
  vec3 tex = texture(flowTex, vec2(advected.x, 1.0-advected.y)).rgb;
  float lum = dot(tex,vec3(0.299,0.587,0.114));
  float strand = pow(max(0.0,sin(q.y*45.0+sin(q.x*19.0+time*1.8)*2.1+time*2.5)),10.0);
  float travelling = pow(max(0.0,sin(q.x*18.0+time*5.5+q.y*4.0)),14.0);
  float value = clamp(lum*1.04+strand*0.43+travelling*0.39,0.0,1.0);
  vec3 rgb = mix(vec3(0.43,0.095,0.008),vec3(1.0,0.78,0.23),smoothstep(0.1,0.55,value));
  rgb = mix(rgb,vec3(1.0,0.995,0.88),smoothstep(0.59,0.9,value));
  float opacity = a*(0.18+0.82*smoothstep(0.05,0.8,value))*clamp(params.y*0.96,0.0,1.0)*color.a;
  rgb = clamp(rgb*color.rgb*(0.86+params.z*0.35),0.0,1.0);
  return vec4(rgb*opacity,opacity);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

